def q(src,topic,stem,opts,ans,exp,errors,difficulty='进阶',section=None):
    opts=opts.split('|'); errors=errors.split('|'); assert len(opts)==4,(stem,opts)
    ans=[ord(x)-65 for x in ans]; assert len(errors)==4-len(ans),(stem,errors)
    er=dict(zip([i for i in range(4) if i not in ans],errors))
    order=list(range(4));random.Random(371+len(Q)*19).shuffle(order)
    newans=[chr(65+i) for i,k in enumerate(order) if k in ans]
    sid,title,sec,ver=S[src]
    Q.append({'id':f'FDE-M3-{len(Q)+1:03}','module':'M3','topic':topic,'type':'single' if len(ans)==1 else 'multiple','stem':stem,'options':{chr(65+i):opts[k] for i,k in enumerate(order)},'answer':newans,'explanation':exp,'distractors':{chr(65+i):er[k] for i,k in enumerate(order) if k not in ans},'difficulty':difficulty,'sources':[{'url':'https://cloud.tencent.com/document/product/1759/'+sid,'title':title,'section':section or sec,'fact':exp.split('。')[0]+'。','verifiedAt':'2026-10-09','version':ver}],'review':{'status':'draft','author':'core_features','reviewer':None,'notes':[]}})
def save():
    OUT.write_text(json.dumps(Q,ensure_ascii=False,indent=2)+'\n'); print(len(Q),sum(x['type']=='single' for x in Q),sum(x['type']=='multiple' for x in Q))
