# 逐题人工修订：将初稿中不相关的干扰改为同一技术概念的常见混淆。
def f(n,opts,why):
    x=Q[n-1];ks=sorted(x['distractors']);vs=opts.split('|');ws=why.split('|');assert len(ks)==len(vs)==len(ws),(n,ks,vs,ws)
    for k,v,w in zip(ks,vs,ws):x['options'][k]=v;x['distractors'][k]=w
